IF OBJECT_ID('DashboardThemes','U') IS NULL BEGIN CREATE TABLE DashboardThemes (restaurant_id VARCHAR(100) PRIMARY KEY, theme_json NVARCHAR(MAX) NULL DEFAULT '{}', created_at DATETIME DEFAULT GETDATE(), updated_at DATETIME DEFAULT GETDATE(), CONSTRAINT FK_DashboardThemes_Restaurants FOREIGN KEY (restaurant_id) REFERENCES Restaurants(id)); END
